local infiniteJumpEnabled=false
local infiniteJumpConn=nil
local infJumpForceJump=false
local infJumpCharacterConn=nil
local infJumpHumanoidConn=nil
local antiBatEnabled=false
local antiBatConn=nil

-- Infinite Jump repris de la logique Violette : boost Y à 50 pendant le saut.
local function hookInfiniteJumpCharacter(char)
    if infJumpHumanoidConn then
        infJumpHumanoidConn:Disconnect()
        infJumpHumanoidConn=nil
    end
    task.wait(0.5)
    if not char or char~=LP.Character then return end
    local hum=char:FindFirstChildOfClass("Humanoid")
    if hum then
        infJumpHumanoidConn=hum.Jumping:Connect(function()
            if infiniteJumpEnabled then
                infJumpForceJump=true
                task.wait(0.1)
                infJumpForceJump=false
            end
        end)
    end
end

infJumpCharacterConn=LP.CharacterAdded:Connect(hookInfiniteJumpCharacter)
if LP.Character then task.spawn(hookInfiniteJumpCharacter,LP.Character) end

local infJumpLastJumpTime=0
local function setInfiniteJump(state)
    state=(state==true)
    infiniteJumpEnabled=state
    _G.NOVYXInfiniteJumpEnabled=state
    if infiniteJumpConn then
        infiniteJumpConn:Disconnect()
        infiniteJumpConn=nil
    end
    if not state then return end

    -- Logic adapted from the supplied script: boost upward while jump is held.
    infiniteJumpConn=RunService.Heartbeat:Connect(function()
        if not infiniteJumpEnabled then return end
        local char=LP.Character
        if not char then return end
        local hum=char:FindFirstChildOfClass("Humanoid")
        local root=char:FindFirstChild("HumanoidRootPart")
        if not hum or hum.Health<=0 or not root then return end
        local holdingJump=false
        pcall(function()
            holdingJump=UIS:IsKeyDown(Enum.KeyCode.Space)
                or UIS:IsKeyDown(Enum.KeyCode.ButtonA)
                or hum.Jump==true
        end)
        if holdingJump and (tick()-infJumpLastJumpTime)>=0.08 then
            infJumpLastJumpTime=tick()
            local vel=root.Velocity
            root.Velocity=Vector3.new(vel.X,55,vel.Z)
        end
    end)

    if not _G.NOVYXInfJumpInputConn then
        _G.NOVYXInfJumpInputConn=UIS.InputBegan:Connect(function(input,gameProcessed)
            if gameProcessed or not infiniteJumpEnabled then return end
            if input.KeyCode==Enum.KeyCode.Space or input.KeyCode==Enum.KeyCode.ButtonA then
                infJumpLastJumpTime=tick()-0.08
            end
        end)
    end
    -- Also support touch devices, which use JumpRequest.
    if not _G.NOVYXInfJumpTouchConn then
        _G.NOVYXInfJumpTouchConn=UIS.JumpRequest:Connect(function()
            if not infiniteJumpEnabled then return end
            local char=LP.Character
            local hum=char and char:FindFirstChildOfClass("Humanoid")
            local root=char and char:FindFirstChild("HumanoidRootPart")
            if not hum or hum.Health<=0 or not root then return end
            local vel=root.Velocity
            if vel.Y<55 then root.Velocity=Vector3.new(vel.X,55,vel.Z) end
        end)
    end
end

local function setAntiBat(state)
    state=(state==true)
    antiBatEnabled=state
    _G.NOVYXAntiBatEnabled=state
    if antiBatConn then
        antiBatConn:Disconnect()
        antiBatConn=nil
    end
    if not state then return end
    antiBatConn=RunService.Heartbeat:Connect(function()
        if not antiBatEnabled then return end
        local char=LP.Character
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        -- Anti Bat may change horizontal velocity, but must never restore an old Y
        -- velocity: doing so can cancel the Infinite Jump's upward boost.
        local originalVelocity=root.Velocity
        root.Velocity=Vector3.new(math.random(-4000,4000),originalVelocity.Y,math.random(-4000,4000))
        RunService.RenderStepped:Wait()
        if root and root.Parent then
            local currentVelocity=root.Velocity
            root.Velocity=Vector3.new(originalVelocity.X,currentVelocity.Y,originalVelocity.Z)
        end
    end)
end

