                if not ch then return false end
                for _, obj in ipairs(ch:GetChildren()) do
                    if obj:IsA("Tool") then
                        local n = obj.Name:lower()
                        if obj:FindFirstChild("Handle") or n:find("animal", 1, true) or n:find("pet", 1, true) then
                            return true
                        end
                    end
                end
                return false
            end

            local function getAttacker()
