                            local hum = ch:FindFirstChildOfClass("Humanoid")
                            if hum then pcall(function() hum:EquipTool(obj) end) end
                            return obj
                        end
                    end
                end
                if bp then
                    for _, obj in ipairs(bp:GetChildren()) do
                        if obj:IsA("Tool") then
                            local hum = ch:FindFirstChildOfClass("Humanoid")
                            if hum then pcall(function() hum:EquipTool(obj) end) end
                            return obj
                        end
                    end
                end
                return nil
            end

            local function swing()
